mapper.select:
SELECT * FROM (
  SELECT * FROM game_chat_message
   WHERE tournament_id = #{tournamentId} AND channel = #{channel}


      AND match_id IS NULL


      AND match_id = #{matchId}



    AND ((from_user_id = #{userA} AND to_user_id = #{userB})
      OR (from_user_id = #{userB} AND to_user_id = #{userA}))

   ORDER BY created_at DESC
   LIMIT #{limit}
) recent ORDER BY created_at ASC
